import XCTest
@testable import Detour

/// Replays content/drill-test-vectors.json, which is generated by the web app's drill code.
final class DrillTests: XCTestCase {
    private struct Vectors: Decodable {
        struct Round: Decodable {
            struct Problem: Decodable {
                let prompt: String
                let answer: Double
            }
            let track: String
            let level: Int
            let seed: UInt32
            let problems: [Problem]
        }
        struct Number: Decodable {
            let input: String
            let value: Double?
        }
        let rounds: [Round]
        let numbers: [Number]
    }

    private func loadVectors() throws -> Vectors {
        let url = try XCTUnwrap(Bundle(for: DrillTests.self).url(forResource: "drill-test-vectors", withExtension: "json"), "drill vectors not bundled")
        return try JSONDecoder().decode(Vectors.self, from: Data(contentsOf: url))
    }

    func testRoundsMatchTheWebGenerator() throws {
        let vectors = try loadVectors()
        XCTAssertFalse(vectors.rounds.isEmpty)
        for round in vectors.rounds {
            let spec = DrillSpec(track: TrackId(rawValue: round.track)!, level: round.level, seed: round.seed)
            let mine = Drills.generateRound(spec)
            let label = "\(round.track) level \(round.level) seed \(round.seed)"
            XCTAssertEqual(mine.map { $0.prompt }, round.problems.map { $0.prompt }, label)
            for (a, b) in zip(mine, round.problems) {
                XCTAssertEqual(a.answer, b.answer, accuracy: 1e-9, "\(label): \(a.prompt)")
            }
        }
    }

    func testNumberParsingMatchesTheWeb() throws {
        for n in try loadVectors().numbers {
            let parsed = Drills.parseNumber(n.input)
            if let expected = n.value {
                XCTAssertEqual(try XCTUnwrap(parsed, "'\(n.input)' should parse"), expected, accuracy: 1e-9, n.input)
            } else {
                XCTAssertNil(parsed, "'\(n.input)' should not parse")
            }
        }
    }

    func testJudging() {
        let p = DrillProblem(prompt: "2 + 2", answer: 4, hint: nil)
        XCTAssertTrue(Drills.judge(.mentalMath, p, input: "4").correct)
        XCTAssertFalse(Drills.judge(.mentalMath, p, input: "5").correct)
        let e = DrillProblem(prompt: "?", answer: 1000, hint: nil)
        XCTAssertTrue(Drills.judge(.estimation, e, input: "1800").correct)
        XCTAssertFalse(Drills.judge(.estimation, e, input: "300").correct)
        XCTAssertFalse(Drills.judge(.estimation, e, input: "lots").correct)
    }

    func testLevelingNeedsTwentyAttemptsAtEightyPercent() {
        func results(_ right: Int, _ total: Int) -> [Bool] { (0..<total).map { $0 < right } }
        XCTAssertFalse(Skills.shouldLevelUp(results(16, 19)))
        XCTAssertFalse(Skills.shouldLevelUp(results(15, 20)))
        XCTAssertTrue(Skills.shouldLevelUp(results(16, 20)))

        var p = SkillProgress(track: .mentalMath)
        var leveledUp = false
        for round in 0..<7 {
            (p, leveledUp) = Skills.apply(p, results: [true, true, true], now: Date(timeIntervalSince1970: Double(round)))
        }
        XCTAssertEqual(p.level, 2)
        XCTAssertEqual(p.attemptsTotal, 21)
        XCTAssertTrue(p.recentResults.isEmpty)
        XCTAssertTrue(leveledUp)
    }

    func testTracksAlternateLeastRecentFirst() {
        XCTAssertEqual(Skills.nextTrack([]), .mentalMath)
        var m = SkillProgress(track: .mentalMath); m.lastAt = Date(timeIntervalSince1970: 10)
        XCTAssertEqual(Skills.nextTrack([m]), .estimation)
        var e = SkillProgress(track: .estimation); e.lastAt = Date(timeIntervalSince1970: 20)
        XCTAssertEqual(Skills.nextTrack([m, e]), .mentalMath)
    }

    func testScoring() {
        XCTAssertEqual(Scoring.timesOff(100, 100), 1, accuracy: 1e-12)
        XCTAssertEqual(Scoring.timesOff(50, 100), 2, accuracy: 1e-9)
        XCTAssertEqual(Scoring.estimationVerdict(105, 100), "Spot on")
        XCTAssertEqual(Scoring.closeness(guess: 71, answer: 71, lo: 0, hi: 100, scale: "linear"), 1)
        XCTAssertEqual(Scoring.closeness(guess: 0, answer: 100, lo: 0, hi: 100, scale: "linear"), 0)
    }
}
